INSERT INTO `persoon` VALUES ('Röell','','Willem Frederik',1,NULL,'',1767,1835,'Adelspredicaat: 1815/adelstitel: 1819.\r\nOverig: bij KB van 20 juni 1810 no. 26 werd aan Röell twee maanden verlof verleend om de wateren te gaan gebruiken.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,'1767-01-01','1835-12-31','Röell',6,1,0,0,1,0,0),('Mollerus','','Johan Hendrik',1,NULL,'Westkerke en Wulpendaal',1750,1834,'Adelspredicaat: 1816/adelstitel: 1820.\r\nOverig: Mollerus werd op 27 mei 1809 met de rang en het traktement van Minister belast met de uitvoering van de Wet omtrent de Constitutionele Adel.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,2,'1750-01-01','1834-12-31','Mollerus',NULL,1,0,0,1,0,0),('Lodewijk Napoleon','',NULL,0,NULL,'',1778,1846,NULL,2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,3,'1778-01-01','1846-12-31','Lodewijk Napoleon',NULL,NULL,0,0,0,0,0),('Crommelin','van Wickevoort','Jan Pieter',0,NULL,'',1763,1837,NULL,2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,4,'1763-01-01','1837-12-31','van Wickevoort Crommelin',NULL,NULL,0,0,0,0,0),('Appelius','','Jean Henry',0,NULL,'',1767,1828,'Overig: na 13 februari 1807 was Appelius zowel Secretaris-Generaal als lid van de Staatsraad in gewone dienst. In september 1808 kwam hij in Buitengewone Dienst.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,5,'1767-01-01','1828-12-31','Appelius',NULL,NULL,0,0,0,0,0),('Cambier','','Jacob Jan',0,NULL,'',1756,1831,'Overig: bij KB van 3 maart 1810 no. 1 werd Cambier reeds tijdelijk mede belast met de portefeuille van Oorlog.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,6,'1756-01-01','1831-12-31','Cambier',NULL,NULL,0,0,0,0,0),('Reuvens','','Jan Everard',0,NULL,'',1763,1816,'Overig: Reuvens werd bij KB van 3 maart 1810 no. 1 reeds belast met de portefeuille van Minister Vice-President van de Staatsraad, met zitting in de Raad van Ministers.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,7,'1763-01-01','1816-12-31','Reuvens',NULL,NULL,0,0,0,0,0),('Dassevael','','Steven',0,NULL,'',1771,1838,'Overig: op 31 december 1810 werd besloten dat Dassevael voorlopig de functie zou uitoefenen van Archivist van het Commandement van het Generaal Gouvernement van Holland.\r\nOp 9 maart 1798 was Dassevael voor het Provisioneel Uitvoerend Bewind gerequireerd.\r\nOp 15 mei 1798 bedankt Dassevael voor zijn post als algemeen secretaris van het Uitvoerend Bewind omdat hij de in de Staatsregeling van mei 1798 vereiste leeftijd van dertig jaar nog niet had bereikt. Hem werd verzocht te continueren in afwachting van een rapport van Vreede.\r\nOp 18 september 1801 schaarde Dassevael zich aan de zijde van president Ermerins in het conflict met andere leden van het Uitvoerend Bewind inzake de invoering van de nieuwe constitutie. Hij verliet de vergadering en Pijman nam de taak van secretaris op zich. Verder heeft hij geen consequenties getrokken.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,8,'1771-01-01','1838-12-31','Dassevael',NULL,NULL,0,0,0,0,0),('Groen van Prinsterer','','Petrus Jacobus',0,NULL,'',1764,1837,NULL,2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,9,'1764-01-01','1837-12-31','Groen van Prinsterer',NULL,NULL,0,0,0,0,0),('Aeneae','','Henricus',0,NULL,'',1743,1810,NULL,2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,10,'1743-01-01','1810-12-31','Aeneae',NULL,NULL,0,0,0,0,0),('Twent van Raephorst','','Adriaan Pieter',1,NULL,'Raaphorst en Rozenburg',1745,1816,'Adelstitels: graaf van Rozenburg 1810, comte 1811.\r\nOverig: Twent werd op 6 juli 1806 benoemd tot Honorair Kamerheer van Lodewijk Napoleon.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,11,'1745-01-01','1816-12-31','Twent van Raephorst',NULL,4,0,0,1,0,0),('Goes','van der','Maarten',1,NULL,'',1751,1826,'Adelstitels: baron (Empire) 1813/jonkheer 1814/baron 1821.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,12,'1751-01-01','1826-12-31','van der Goes',NULL,1,0,0,1,0,0),('Bosscha','','Johannes',0,NULL,'',1767,1810,NULL,2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,13,'1767-01-01','1810-12-31','Bosscha',NULL,NULL,0,0,0,0,0),('Hooff','van','Joannes Franciscus Rudolphus',0,NULL,'',1755,1